Punycode encode (RFC 3492):

```js
const BASE = 36, TMIN = 1, TMAX = 26, SKEW = 38, DAMP = 700, INITIAL_BIAS = 72, INITIAL_N = 128, DELIMITER = '-';

function adapt(delta, numPoints, firstTime) {
  delta = firstTime ? Math.floor(delta / DAMP) : delta >> 1;
  delta += Math.floor(delta / numPoints);
  let k = 0;
  while (delta > Math.floor(((BASE - TMIN) * TMAX) / 2)) {
    delta = Math.floor(delta / (BASE - TMIN));
    k += BASE;
  }
  return k + Math.floor(((BASE - TMIN + 1) * delta) / (delta + SKEW));
}

function digitToBasic(d) { return String.fromCharCode(d < 26 ? 97 + d : 48 + (d - 26)); }
function basicToDigit(cp) {
  if (cp >= 48 && cp < 58) return 26 + (cp - 48);
  if (cp >= 65 && cp < 91) return cp - 65;
  if (cp >= 97 && cp < 123) return cp - 97;
  return BASE;
}
```

