export function punycodeEncode(input) {
  const cps = Array.from(input).map(c => c.codePointAt(0));
  let n = INITIAL_N, delta = 0, bias = INITIAL_BIAS;
  const output = [];
  const b = cps.filter(cp => cp < 0x80);
  for (const cp of b) output.push(String.fromCharCode(cp));
  let h = b.length;
  if (h > 0 && h < cps.length) output.push(DELIMITER);
  // note: RFC says if b>0 push delimiter; python's punycode adds delimiter only if b>0 and there are non-basic? Python: if b: output.append('-')? Actually Python codecs punycode: always appends delimiter if any basic chars. For encode of 'café': 'caf-...' wait encoded is 'caf-dma' — has delimiter. For 'προγραμματισμός' no basics: 'mxaae0anacrikcslm7j' no delimiter. Python punycode adds delimiter whenever b>0 even if all basic (but then idna wouldn't call punycode). RFC says append delimiter if b>0. Fine: append if b>0 (and idna only calls when non-basic exists).
  while (h < cps.length) {
    let m = Infinity;
    for (const cp of cps) if (cp >= n && cp < m) m = cp;
    delta += (m - n) * (h + 1);
    n = m;
    for (const cp of cps) {
      if (cp < n) delta++;
      else if (cp === n) {
        let q = delta;
        for (let k = BASE; ; k += BASE) {
          const t = k <= bias ? TMIN : (k >= bias + TMAX ? TMAX : k - bias);
          if (q < t) break;
          output.push(digitToBasic(t + ((q - t) % (BASE - t))));
          q = Math.floor((q - t) / (BASE - t));
        }
        output.push(digitToBasic(q));
        bias = adapt(delta, h + 1, h === b.length);
        delta = 0;
        h++;
