import * as punycode from './punycode.mjs';

export class IDNAError extends Error { constructor(message){ super(message); this.name='IDNAError'; } }
export class InvalidCodepoint extends IDNAError { this.name='InvalidCodepoint' }

const ALABEL_PREFIX = 'xn--';
const UNICODE_DOT_RE = /[.\u3002\uFF0E\uFF61]/u;

// CONTEXTO / CONTEXTJ codepoints that check_label permits without context evaluation
const EXTRA_ALLOWED = new Set([0x00B7, 0x0375, 0x05F3, 0x30FB, 0x200C, 0x200D]);
const PVALID_RE = /[\p{Ll}\p{Lo}\p{Lm}\p{Mn}\p{Mc}\p{Nd}-]/u;

function asciiLower(s) { return s.replace(/[A-Z]/g, c => c.toLowerCase()); }

function unot(cp) { return 'U+' + cp.toString(16).toUpperCase().padStart(4, '0'); }

function pyStrRepr(s) { ... single quote repr }

export function checkLabel(label) {
  if (label.length === 0) throw new IDNAError('Empty Label');
  if (label.normalize('NFC') !== label) throw new IDNAError('Label must be in Normalization Form C');
  if (label.slice(2, 4) === '--') throw new IDNAError('Label has disallowed hyphens in 3rd and 4th position');
  if (label.startsWith('-') || label.endsWith('-')) throw new IDNAError('Label must not start or end with a hyphen');
  const first = Array.from(label)[0];
  if (/^[\p{Mn}\p{Mc}\p{Me}]/u.test(first)) throw new IDNAError('Label begins with an illegal combining character');
  const chars = Array.from(label);
  for (let i = 0; i < chars.length; i++) {
    const ch = chars[i]; const cp = ch.codePointAt(0);
    if (PVALID_RE.test(ch) || EXTRA_ALLOWED.has(cp)) continue;
    throw new InvalidCodepoint(`Codepoint ${unot(cp)} at position ${i + 1} of ${pyStrRepr(label)} not allowed`);
  }
}
