// RFC 3492 Punycode encoder/decoder, reimplemented in pure JavaScript.
// No external dependencies; no use of Node's built-in `punycode` module.

const BASE = 36;
const TMIN = 1;
const TMAX = 26;
const SKEW = 38;
const DAMP = 700;
const INITIAL_BIAS = 72;
const INITIAL_N = 128;
const DELIMITER = '-';

export class PunycodeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'PunycodeError';
  }
}

function adapt(delta, numPoints, firstTime) {
  delta = firstTime ? Math.floor(delta / DAMP) : Math.floor(delta / 2);
  delta += Math.floor(delta / numPoints);
  let k = 0;
  while (delta > Math.floor(((BASE - TMIN) * TMAX) / 2)) {
    delta = Math.floor(delta / (BASE - TMIN));
    k += BASE;
  }
  return k + Math.floor(((BASE - TMIN + 1) * delta) / (delta + SKEW));
}

// 0..25 -> 'a'..'z', 26..35 -> '0'..'9'
function digitToBasic(digit) {
  return String.fromCharCode(digit + (digit < 26 ? 97 : 22));
}

function basicToDigit(codePoint) {
  if (codePoint >= 0x30 && codePoint < 0x3a) return 26 + (codePoint - 0x30);
  if (codePoint >= 0x41 && codePoint < 0x5b) return codePoint - 0x41;
  if (codePoint >= 0x61 && codePoint < 0x7b) return codePoint - 0x61;
  return BASE;
}

// Encodes a Unicode string into its Punycode form (ASCII output).
export function encode(input) {
  const codePoints = Array.from(input, (ch) => ch.codePointAt(0));
  let n = INITIAL_N;
  let delta = 0;
  let bias = INITIAL_BIAS;
  const output = [];

  const basicCount = codePoints.filter((cp) => cp < 0x80).length;
  for (const cp of codePoints) {
    if (cp < 0x80) output.push(String.fromCharCode(cp));
  }
  let handled = basicCount;
  if (basicCount > 0) output.push(DELIMITER);

  while (handled < codePoints.length) {
    let m = Infinity;
    for (const cp of codePoints) {
      if (cp >= n && cp < m) m = cp;
    }
    if (m === Infinity) throw new PunycodeError('Invalid input');
    delta += (m - n) * (handled + 1);
    n = m;
    for (const cp of codePoints) {
      if (cp < n) {
        delta += 1;
      } else if (cp === n) {
        let q = delta;
        for (let k = BASE; ; k += BASE) {
          const t = k <= bias ? TMIN : k >= bias + TMAX ? TMAX : k - bias;
          if (q < t) break;
          output.push(digitToBasic(t + ((q - t) % (BASE - t))));
          q = Math.floor((q - t) / (BASE - t));
        }
        output.push(digitToBasic(q));
        bias = adapt(delta, handled + 1, handled === basicCount);
        delta = 0;
        handled += 1;
      }
    }
    delta += 1;
    n += 1;
  }
  return output.join('');
}

// Decodes a Punycode string back to Unicode.
export function decode(input) {
  let n = INITIAL_N;
  let i = 0;
  let bias = INITIAL_BIAS;
  const output = [];

  let basicEnd = input.lastIndexOf(DELIMITER);
  if (basicEnd < 0) basicEnd = 0;
  for (let j = 0; j < basicEnd; j++) {
    const cp = input.charCodeAt(j);
    if (cp >= 0x80) throw new PunycodeError('Invalid basic code point');
    output.push(String.fromCharCode(cp));
  }

  let index = basicEnd > 0 ? basicEnd + 1 : 0;
  while (index < input.length) {
    const oldi = i;
    let w = 1;
    for (let k = BASE; ; k += BASE) {
      if (index >= input.length) throw new PunycodeError('Incomplete input');
      const digit = basicToDigit(input.charCodeAt(index));
      index += 1;
      if (digit >= BASE) throw new PunycodeError('Invalid extended code point');
      i += digit * w;
      const t = k <= bias ? TMIN : k >= bias + TMAX ? TMAX : k - bias;
      if (digit < t) break;
      w *= BASE - t;
    }
    const outLength = output.length + 1;
    bias = adapt(i - oldi, outLength, oldi === 0);
    n += Math.floor(i / outLength);
    i %= outLength;
    output.splice(i, 0, String.fromCodePoint(n));
    i += 1;
  }
  return output.join('');
}

// Minimal IDNA (Internationalized Domain Names in Applications, IDNA 2008)
// reimplementation matching the observable behaviour of the Python `idna`
// package: encode / decode / alabel / ulabel.
//
// Encoded "byte" results are represented as ASCII strings; the caller is
// responsible for rendering them with Python's bytes-repr formatting.

import * as punycode from './punycode.mjs';
import { pyStrRepr } from './pybytes.mjs';

export class IDNAError extends Error {
  constructor(message) {
    super(message);
    this.name = 'IDNAError';
  }
}

export class InvalidCodepoint extends IDNAError {
  constructor(message) {
    super(message);
    this.name = 'InvalidCodepoint';
  }
}

const ALABEL_PREFIX = 'xn--';
// Python idna splits domains on these four dot characters (strict=False).
const UNICODE_DOTS_RE = /[.。｡]/u;

// RFC 5892 PVALID approximation via Unicode general categories, plus the
// CONTEXTO codepoints (00B7, 0375, 05F3, 30FB) and CONTEXTJ codepoints
// (200C, 200D) which the non-strict check_label permits.
const PVALID_RE = /[\p{Ll}\p{Lo}\p{Lm}\p{Mn}\p{Mc}\p{Nd}-]/u;
const EXTRA_ALLOWED = new Set([0x00b7, 0x0375, 0x05f3, 0x30fb, 0x200c, 0x200d]);
const COMBINING_RE = /[\p{Mn}\p{Mc}\p{Me}]/u;

function isAscii(s) {
  return /^[\x00-\x7f]*$/.test(s);
}

// bytes.lower() equivalent: ASCII-only lowercasing.
function asciiLower(s) {
  return s.replace(/[A-Z]/g, (c) => c.toLowerCase());
}

function unot(cp) {
  return 'U+' + cp.toString(16).toUpperCase().padStart(4, '0');
}

function validLabelLength(label) {
  return label.length > 0 && label.length <= 63;
}

function validStringLength(label, trailingDot) {
  return label.length <= (trailingDot ? 254 : 253);
}

export function checkLabel(label) {
  if (label.length === 0) {
    throw new IDNAError('Empty Label');
  }
  if (label.normalize('NFC') !== label) {
    throw new IDNAError('Label must be in Normalization Form C');
  }
  if (label.slice(2, 4) === '--') {
    throw new IDNAError('Label has disallowed hyphens in 3rd and 4th position');
  }
  if (label.startsWith('-') || label.endsWith('-')) {
    throw new IDNAError('Label must not start or end with a hyphen');
  }
  const chars = Array.from(label);
  if (COMBINING_RE.test(chars[0])) {
    throw new IDNAError('Label begins with an illegal combining character');
  }
  for (let pos = 0; pos < chars.length; pos++) {
    const ch = chars[pos];
    const cp = ch.codePointAt(0);
    if (PVALID_RE.test(ch) || EXTRA_ALLOWED.has(cp)) continue;
    throw new InvalidCodepoint(
      `Codepoint ${unot(cp)} at position ${pos + 1} of ${pyStrRepr(label)} not allowed`
    );
  }
}

// Converts a Unicode label to its A-label (ASCII) form, returned as an
// ASCII string standing in for Python's bytes result.
export function alabel(label) {
  if (isAscii(label)) {
    ulabel(label); // validation only
    if (!validLabelLength(label)) {
      throw new IDNAError('Label too long');
    }
    return label;
  }
  if (!label) {
    throw new IDNAError('No Input');
  }
  checkLabel(label);
  const result = ALABEL_PREFIX + punycode.encode(label);
  if (!validLabelLength(result)) {
    throw new IDNAError('Label too long');
  }
  return result;
}

// Converts an A-label (ASCII string standing in for bytes) to a U-label.
export function ulabel(label) {
  const lower = asciiLower(label);
  if (lower.startsWith(ALABEL_PREFIX)) {
    const rest = lower.slice(ALABEL_PREFIX.length);
    if (!rest) {
      throw new IDNAError('Malformed A-label, no Punycode eligible content found');
    }
    if (rest.endsWith('-')) {
      throw new IDNAError('A-label must not end with a hyphen');
    }
    let decoded;
    try {
      decoded = punycode.decode(rest);
    } catch {
      throw new IDNAError('Invalid A-label');
    }
    checkLabel(decoded);
    return decoded;
  }
  checkLabel(lower);
  return lower;
}

// Encodes a full Unicode domain name to its ASCII-compatible form.
export function encode(domain) {
  const labels = domain.split(UNICODE_DOTS_RE);
  let trailingDot = false;
  if (labels.length > 0 && labels[labels.length - 1] === '') {
    trailingDot = true;
    labels.pop();
  }
  if (labels.length === 0) {
    throw new IDNAError('Empty domain');
  }
  const result = labels.map((label) => alabel(label));
  let joined = result.join('.');
  if (trailingDot) joined += '.';
  if (!validStringLength(joined, trailingDot)) {
    throw new IDNAError('Domain too long');
  }
  return joined;
}

// Decodes an ASCII-compatible domain name back to Unicode.
export function decode(domain) {
  const labels = domain.split('.');
  let trailingDot = false;
  if (labels.length > 0 && labels[labels.length - 1] === '') {
    trailingDot = true;
    labels.pop();
  }
  if (labels.length === 0) {
    throw new IDNAError('Empty domain');
  }
  const result = labels.map((label) => ulabel(label));
  let joined = result.join('.');
  if (trailingDot) joined += '.';
  return joined;
}

// Helpers reproducing CPython's repr() formatting for bytes and str objects,
// so that console.log output matches Python's print() byte-for-byte.

// repr() of a bytes object, e.g. b'xn--caf-dma.fr'
export function bytesRepr(asciiBytes) {
  const hasSingle = asciiBytes.includes("'");
  const hasDouble = asciiBytes.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = 'b' + quote;
  for (const ch of asciiBytes) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\t') out += '\\t';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (cp < 0x20 || cp >= 0x7f) out += '\\x' + cp.toString(16).padStart(2, '0');
    else out += ch;
  }
  return out + quote;
}

function isPrintable(ch) {
  // Approximation of str.isprintable(): reject control, separator (except
  // space) and unassigned/surrogate characters.
  return !/[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u.test(ch) || ch === ' ';
}

// repr() of a str object, e.g. 'CAFÉ'
export function pyStrRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\t') out += '\\t';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (!isPrintable(ch)) {
      if (cp <= 0xff) out += '\\x' + cp.toString(16).padStart(2, '0');
      else if (cp <= 0xffff) out += '\\u' + cp.toString(16).padStart(4, '0');
      else out += '\\U' + cp.toString(16).padStart(8, '0');
    } else out += ch;
  }
  return out + quote;
}

// Minimal reimplementation of the argparse behaviour used by test1.py:
//   parser.add_argument('--domain', type=str, required=True)
// Supports: "--domain VALUE", "--domain=VALUE", unambiguous prefix
// abbreviations (e.g. "--dom"), "-h/--help", "--" separator, and argparse's
// exit codes (0 for help, 2 for usage errors).

import process from 'node:process';
import { basename } from 'node:path';

const PROG = basename(process.argv[1] || 'test1.mjs');
const USAGE = `usage: ${PROG} [-h] --domain DOMAIN`;
const OPTION_STRINGS = ['--help', '--domain'];
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

function usageError(message) {
  process.stderr.write(USAGE + '\n');
  process.stderr.write(`${PROG}: error: ${message}\n`);
  process.exit(2);
}

function printHelp() {
  process.stdout.write(
    USAGE +
      '\n' +
      '\n' +
      'options:\n' +
      '  -h, --help       show this help message and exit\n' +
      '  --domain DOMAIN\n'
  );
  process.exit(0);
}

// Mirrors argparse: a token starting with '-' is option-like unless it is a
// lone '-', a negative number, or contains a space.
function looksLikeOption(token) {
  if (!token.startsWith('-')) return false;
  if (token === '-') return false;
  if (NEGATIVE_NUMBER_RE.test(token)) return false;
  if (token.includes(' ')) return false;
  return true;
}

export function parseArgs(argv) {
  let domain;
  let domainSeen = false;
  const extras = [];
  let sawDoubleDash = false;
  let i = 0;

  while (i < argv.length) {
    const token = argv[i];

    if (!sawDoubleDash && token === '--') {
      sawDoubleDash = true;
      i += 1;
      continue;
    }

    if (!sawDoubleDash && token.startsWith('--')) {
      let name = token;
      let inlineValue;
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }

      let matched = null;
      if (OPTION_STRINGS.includes(name)) {
        matched = name;
      } else {
        const candidates = OPTION_STRINGS.filter((opt) => opt.startsWith(name));
        if (candidates.length === 1) {
          matched = candidates[0];
        } else if (candidates.length > 1) {
          usageError(`ambiguous option: ${name} could match ${candidates.join(', ')}`);
        }
      }

      if (matched === null) {
        extras.push(token);
        i += 1;
        continue;
      }
      if (matched === '--help') {
        printHelp();
      }
      // matched === '--domain'
      if (inlineValue !== undefined) {
        domain = inlineValue;
        domainSeen = true;
        i += 1;
      } else {
        const next = argv[i + 1];
        if (next === undefined || looksLikeOption(next)) {
          usageError('argument --domain: expected one argument');
        }
        domain = next;
        domainSeen = true;
        i += 2;
      }
      continue;
    }

    if (!sawDoubleDash && looksLikeOption(token)) {
      if (token === '-h') {
        printHelp();
      }
      extras.push(token);
      i += 1;
      continue;
    }

    extras.push(token);
    i += 1;
  }

  if (!domainSeen) {
    usageError('the following arguments are required: --domain');
  }
  if (extras.length > 0) {
    usageError(`unrecognized arguments: ${extras.join(' ')}`);
  }
  return { domain };
}

// Entry point — ESM port of test1.py.
// Usage: node test1.mjs --domain <domain>

import process from 'node:process';
import { parseArgs } from './lib/argparse.mjs';
import { encode, decode, ulabel, alabel, IDNAError } from './lib/idna.mjs';
import { bytesRepr } from './lib/pybytes.mjs';

function main() {
  const args = parseArgs(process.argv.slice(2));
  const domain = args.domain;

  // Encode the domain to ASCII-compatible form (printed as Python bytes repr)
  const encoded = encode(domain);
  console.log(bytesRepr(encoded));

  // Decode the encoded domain back to Unicode
  const decoded = decode(encoded);
  console.log(decoded);

  // Demonstrate ulabel()/alabel() on the first label
  const firstLabel = domain.split('.')[0];
  if (firstLabel) {
    const ulabelResult = ulabel(encode(firstLabel));
    console.log(ulabelResult);

    const alabelResult = alabel(firstLabel);
    console.log(bytesRepr(alabelResult));
  }
}

try {
  main();
} catch (err) {
  if (err instanceof IDNAError) {
    // Mirror the final line of the Python traceback; uncaught exceptions
    // in CPython exit with status 1.
    process.stderr.write(`idna.core.${err.name}: ${err.message}\n`);
    process.exit(1);
  }
  throw err;
}

