// IDNA2008 character tables, derived black-box from the reference
// implementation. Each table is a sorted list of inclusive codepoint ranges.
// Filled in by the discovery step; see checkLabel/validContextj in idna.mjs.

// DISALLOWED: codepoints in PVALID general categories that IDNA2008 rejects.
export const DISALLOWED = [];

// Joining types (RFC 5892 Appendix A.1) for cursive scripts.
export const JOINING_L = [];
export const JOINING_R = [];
export const JOINING_D = [];

// VIRAMA: codepoints with canonical combining class 9 (RFC 5892 Appendix A.2).
export const VIRAMA = [];

// Binary search of a codepoint in a sorted inclusive-range list.
export function inRanges(ranges, cp) {
  let lo = 0;
  let hi = ranges.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (cp < ranges[mid][0]) hi = mid - 1;
    else if (cp > ranges[mid][1]) lo = mid + 1;
    else return true;
  }
  return false;
}

