import * as punycode from './punycode.mjs';
import { pyStrRepr } from './pybytes.mjs';
import { DISALLOWED, JOINING_L, JOINING_R, JOINING_D, VIRAMA, inRanges } from './idna_tables.mjs';

export class IDNAError extends Error {
  constructor(message) {
    super(message);
    this.name = 'IDNAError';
  }
}

export class InvalidCodepoint extends IDNAError {
  constructor(message) {
    super(message);
    this.name = 'InvalidCodepoint';
  }
}

export class InvalidCodepointContext extends IDNAError {
  constructor(message) {
    super(message);
    this.name = 'InvalidCodepointContext';
  }
}

export class IDNABidiError extends IDNAError {
  constructor(message) {
    super(message);
    this.name = 'IDNABidiError';
  }
}

const ALABEL_PREFIX = 'xn--';
// Python idna splits domains on these four dot characters (strict=False).
const UNICODE_DOTS_RE = /[.。．｡]/u;

// RFC 5892 PVALID approximation via Unicode general categories; the exact
// exceptions are captured in the DISALLOWED table.
const PVALID_RE = /[\p{Ll}\p{Lo}\p{Lm}\p{Mn}\p{Mc}\p{Nd}-]/u;
const COMBINING_RE = /[\p{Mn}\p{Mc}\p{Me}]/u;
const CP_CONTEXTO = new Set([0x00b7, 0x0375, 0x05f3, 0x30fb]);
const CP_CONTEXTJ = new Set([0x200c, 0x200d]);

const GREEK_RE = /\p{Script=Greek}/u;
const HEBREW_RE = /\p{Script=Hebrew}/u;
const KANA_HAN_RE = /[\p{Script=Hiragana}\p{Script=Katakana}\p{Script=Han}]/u;

